"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[5946],{4265:(e,t,i)=>{i.r(t),i.d(t,{assets:()=>l,contentTitle:()=>o,default:()=>m,frontMatter:()=>s,metadata:()=>r,toc:()=>c});var n=i(4848),a=i(8453);const s={sidebar_position:7},o="7.Optimized Investment Strategies",r={id:"AM Steps/OptimizeInvestment",title:"7.Optimized Investment Strategies",description:"Optimization",source:"@site/docs/AM Steps/OptimizeInvestment.md",sourceDirName:"AM Steps",slug:"/AM Steps/OptimizeInvestment",permalink:"/AssetManagement/docs/AM Steps/OptimizeInvestment",draft:!1,unlisted:!1,tags:[],version:"current",sidebarPosition:7,frontMatter:{sidebar_position:7},sidebar:"tutorialSidebar",previous:{title:"6. Determine Asset Risk",permalink:"/AssetManagement/docs/AM Steps/Risk"},next:{title:"8. Determine Funding Strategy",permalink:"/AssetManagement/docs/AM Steps/Funding"}},l={},c=[{value:"Optimization",id:"optimization",level:2},{value:"Prioritization and Optimization Approaches",id:"prioritization-and-optimization-approaches",level:2},{value:"Capital Investment Strategies",id:"capital-investment-strategies",level:2},{value:"Maintenance Programs",id:"maintenance-programs",level:2}];function d(e){const t={a:"a",admonition:"admonition",h1:"h1",h2:"h2",li:"li",p:"p",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.h1,{id:"7optimized-investment-strategies",children:"7.Optimized Investment Strategies"}),"\n",(0,n.jsx)(t.h2,{id:"optimization",children:"Optimization"}),"\n",(0,n.jsx)(t.p,{children:"In simple terms, optimization involves methods that aim to improve outcomes to the greatest extent possible. In infrastructure management, optimization techniques are primarily used to allocate capital or operations and maintenance (O&M) budgets efficiently, with the goal of improving levels of service."}),"\n",(0,n.jsx)(t.p,{children:"An optimization problem consists of objectives, constraints, and decision variables. Objectives could include minimizing costs, minimizing risks, or maximizing asset condition. Constraints may encompass budget limitations, regulatory requirements, minimum levels of service, worker availability, or equipment availability. Decision variables represent the elements the optimization process will adjust to achieve the defined objectives within the constraints\u2014such as selecting assets for replacement or maintenance. These examples are not exhaustive; asset managers must tailor the optimization problem to reflect the unique characteristics and available data of their system. For instance, in some cases, levels of service might be considered as constraints, while in others they might be the main objective."}),"\n",(0,n.jsx)(t.p,{children:"Multiple objectives can also be defined, but to identify the best overall solution, these objectives should be weighted, allowing for a single composite objective to guide the decision-making process. Consider the example of optimizing a capital budget by selecting assets for replacement. If there is only one objective\u2014minimizing risk within a fixed budget\u2014the assets with the highest risk scores would be prioritized for replacement until the budget is exhausted. If the objectives are dual (e.g., minimizing both risk and cost), various combinations of asset replacements would need to be tested, with the resulting risk and cost outcomes of each scenario compared. To select the optimal solution, an overall score could be computed by assigning weights to risk and cost. A useful approach here is to determine the Pareto front, which represents the set of best risk-cost combinations where any improvement in one objective would lead to a compromise in the other. Ultimately, the organization would select a point on the Pareto front, thereby implicitly prioritizing risk versus cost according to its goals"}),"\n",(0,n.jsx)(t.h2,{id:"prioritization-and-optimization-approaches",children:"Prioritization and Optimization Approaches"}),"\n",(0,n.jsx)(t.p,{children:"Prioritization and optimization methods in asset management range from simple subjective rankings to advanced mathematical models, each with its own advantages and limitations. The simplest approach is a subjective ranking based on judgment, which, while quick and easy, is highly susceptible to bias and may not yield optimal results. Ranking methods based on specific parameters, such as levels of service or asset condition, are also straightforward and user-friendly but may still fall short of optimal solutions. Adding economic analysis or risk assessment to parameter-based rankings provides a slightly more refined approach that is reasonably simple while bringing results closer to optimal."}),"\n",(0,n.jsx)(t.p,{children:'Mathematical programming models used for optimization are more complex but can yield near-optimal solutions. These models can optimize budgets on a year-by-year basis, though they often overlook the timing of interventions. Comprehensive optimization, which uses mathematical programming to determine the best combination of interventions based on "which assets, what actions, and when," is the most complex approach but can yield highly optimized programs that balance maximizing benefits with minimizing costs.'}),"\n",(0,n.jsx)(t.p,{children:"Advanced computational techniques such as genetic algorithms offer alternative methods for complex optimization problems. Genetic algorithms are widely used as heuristic search tools that can explore numerous combinations to approach an optimal solution. Overall, while simpler methods are easier to apply and interpret, more sophisticated optimization approaches can offer substantial benefits by providing cost-effective and strategic asset management solutions."}),"\n",(0,n.jsx)(t.h2,{id:"capital-investment-strategies",children:"Capital Investment Strategies"}),"\n",(0,n.jsx)(t.p,{children:"Capital investment refers to either asset replacement or rehabilitation. Replacement involves substituting an existing asset, which could be a like-for-like swap or an upgrade that improves the level of service. For example, replacing an outdated piece of equipment with a more efficient model, or installing a higher-capacity asset to meet growing demand, aligns with goals of enhancing service or adapting to new standards.  When setting up capital investment optimization, budgets are often defined as a constraint, dictating the extent of feasible improvements within a given fiscal period."}),"\n",(0,n.jsx)(t.p,{children:"Because capital projects are generally large-scale, as compared to regular maintenance, it is more effective to analyze the asset systems together rather than in isolation. Coordinated investment strategies, often referred to as corridor replacements, allow for synchronized planning of adjacent assets, such as roads, water mains, and sewer lines. This approach reduces costs, especially for traditional open cut pipe replacement, and also minimizes disruptions to the community."}),"\n",(0,n.jsx)(t.p,{children:'Today, a wide range of software solutions are available that integrate data from various asset systems, perform the necessary optimization, and provide a prioritized list of capital projects. These tools streamline decision-making and for this reason are known as "Decision Support Systems". Examples include Assetic, Deighton Total Infrastructure Management System (dTIMS), Infrastructure Data Solutions (IDS) Asset Optimizer, PowerPlan, CityWide, and Direxyon Asset Investment Planning (AIP).'}),"\n",(0,n.jsx)(t.admonition,{title:"Case Study: Vancouver, Canada \u2013 Collaborative Infrastructure Governance",type:"info",children:(0,n.jsxs)(t.p,{children:["Vancouver's ",(0,n.jsx)(t.a,{href:"https://www.weforum.org/agenda/2023/05/vancouver-cities-develop-better-infrastructure-planning-development/",children:"collaborative infrastructure governance model"}),' has recently stood out as a powerful approach to infrastructure planning and development. The city, facing challenges of affordability, rapid growth, climate resilience, and citizen well-being, adopted an innovative model that promotes multi-layered cooperation across various government departments. This was not a rapid, one-time change, but rather a long-term effort requiring consistent commitment and active engagement from all parties. The model fostered improved dialogue through director meetings, ensured transparency around priorities, and fostered strategic alignment across departments. Collaborative governance was developed through the following steps: integrating city-level priorities into departmental plans via a "layered" system, connecting departments to ensure consistency and coordination, incentivizing \u201cwin-win\u201d models for jointly funded projects, focusing on outcome-driven project delivery, and instilling a culture that is flexible and responsive to stakeholder feedback.\nAn example of the model\u2019s application is the "One Water Approach," an integrated infrastructure plan that emphasizes cross-departmental collaboration for water and watershed-related services. All planning, budgeting, and maintenance tasks are shared between stakeholders, with no single agency at the center of the process. Instead, the needs of the utility and all levels of government take precedence. The success of this model can be seen in the Alberta Street Blue Green System, a project that impacted pedestrian mobility, green space, sewage, wastewater, stormwater, broadband, and public space quality. This case underscores the transformative potential of aligning asset management and urban planning in enhancing urban sustainability and resilience.']})}),"\n",(0,n.jsx)(t.h2,{id:"maintenance-programs",children:"Maintenance Programs"}),"\n",(0,n.jsx)(t.p,{children:"Maintenance refers to regular or minor interventions carried out to maintain the level of service of an asset and extend its useful life. Effective maintenance programs generally include three key types: corrective, preventive, and predictive maintenance."}),"\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsxs)(t.li,{children:["\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.strong,{children:"Corrective maintenance"})," involves addressing known defects or issues, either as a response to emergencies or as part of deferred maintenance. Emergency corrective maintenance can lead to higher costs due to the potential for additional damage and unplanned disruptions."]}),"\n"]}),"\n",(0,n.jsxs)(t.li,{children:["\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.strong,{children:"Preventive maintenance"})," aims to prevent future failures by scheduling routine servicing and replacing components before issues arise. Preventive maintenance is typically more cost-effective than corrective maintenance because it reduces the likelihood of costly emergency repairs. Additionally, it allows asset managers to time multiple maintenance activities together, creating further opportunities for savings."]}),"\n"]}),"\n",(0,n.jsxs)(t.li,{children:["\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.strong,{children:"Predictive maintenance"})," relies on inspection and condition monitoring to forecast potential failures. The results of these can be used together with deterioration models to better plan preventive maintenance, optimizing the timing of maintenance and reducing the occurrence of unexpected breakdowns."]}),"\n"]}),"\n"]}),"\n",(0,n.jsx)(t.p,{children:"Because corrective maintenance is generally more expensive and disruptive than preventive maintenance, a mature asset management system should strive to increase the ratio of preventive (planned) to corrective (unplanned) maintenance costs, enhancing both cost efficiency and asset reliability. In addition to maintenance costs and % of preventive work, other maintenance key performance indicators (KPIs) include worker availability, % overtime, and % rework."}),"\n",(0,n.jsx)(t.p,{children:"Operations and maintenance (O&M) budgets are typically allocated as a total sum per year, unlike capital budgets, which are tied to specific projects. This approach provides more flexibility for handling corrective maintenance and unplanned work. However, it also increases the risk of underestimating O&M costs, particularly if budgets are not regularly updated to reflect increasing costs as assets age or when new assets are added to the system."}),"\n",(0,n.jsx)(t.p,{children:"O&M budgets must cover a wide range of activities, including but not limited to:"}),"\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Data-related tasks"}),": Data entry, data management, setup, and analysis."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Asset lifecycle management"}),": Installation and commissioning, de-commissioning, and disposal."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Shutdowns and overhauls"}),": Planning, implementation, and management of shutdowns, turnarounds, and overhauls."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Ancillary work"}),": Tasks such as painting and other miscellaneous work."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Personnel management"}),": Managing staff, including training and supervision."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Routine servicing"}),": Regular inspection, checking, and adjusting of assets."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Corrective work"}),": Addressing failures and responding to work requests."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Condition monitoring"}),": Continuous monitoring of asset performance to predict failures."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Failure analysis"}),": Conducting root cause analyses for recurring issues."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Logistics"}),": Travel to and from work locations."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Procurement"}),": Acquiring necessary spares, tools, and equipment."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Planning and supervision"}),": Job scoping, costing, planning, scheduling, and providing technical supervision and support."]}),"\n"]}),"\n",(0,n.jsx)(t.p,{children:"A variety of software systems are also available to optimize maintenance and plan work orders for all types of maintenance. These systems are commonly called Computerized Maintenance Management Systems (CMMS). Examples include CityWorks, Lucity, IBM Maximo and Oracle Utilities."})]})}function m(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},8453:(e,t,i)=>{i.d(t,{R:()=>o,x:()=>r});var n=i(6540);const a={},s=n.createContext(a);function o(e){const t=n.useContext(s);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),n.createElement(s.Provider,{value:t},e.children)}}}]);